using TicTacToe.Domain.Contracts;

namespace TicTacToe.Domain.Entities.GameAggregate;

/// <summary>Child entity of the Game aggregate; the board is derived from moves (no stored board).</summary>
public class Move
{
    private Move()
    {
    }

    /// <summary>Generated by EF on insert (Guid convention): a domain-set key on a child of a tracked
    /// aggregate would make change tracking treat the new move as an existing row (UPDATE → 0 rows).</summary>
    public Guid Id { get; private set; }

    internal Move(Guid gameId, int moveNumber, int position, Mark mark, Guid playerId, DateTime playedAtUtc)
    {
        GameId = gameId;
        MoveNumber = moveNumber;
        Position = position;
        Mark = mark;
        PlayerId = playerId;
        PlayedAtUtc = playedAtUtc;
    }

    public Guid GameId { get; private set; }

    public int MoveNumber { get; private set; }

    public int Position { get; private set; }

    public Mark Mark { get; private set; }

    public Guid PlayerId { get; private set; }

    public DateTime PlayedAtUtc { get; private set; }
}
